sourceFileLike:
/**
 * Subset of properties from SourceFile that are used in multiple utility functions
 */
export interface SourceFileLike {
    readonly text: string;
    /** @internal */
    lineMap?: readonly number[] | undefined;
    /** @internal */
    getPositionOfLineAndCharacter?(line: number, character: number, allowEdits?: true): number;
}

lineMapSource:
/** @internal */
export interface LineMapSource {
    readonly text: string;
    lineMap?: readonly number[] | undefined;
}

starts.before:
/** @internal */
export function getLineStarts(sourceFile: SourceFileLike): readonly number[] {
    return sourceFile.lineMap || (sourceFile.lineMap = computeLineStarts(sourceFile.text));
}

starts.after:
/** @internal */
export function getLineStarts(sourceFile: LineMapSource): readonly number[] {
    return sourceFile.lineMap || (sourceFile.lineMap = computeLineStarts(sourceFile.text));
}

position.before:
export function getLineAndCharacterOfPosition(sourceFile: SourceFileLike, position: number): LineAndCharacter {
    return computeLineAndCharacterOfPosition(getLineStarts(sourceFile), position);
}

position.after:
/** @internal */
export function getLineAndCharacterOfPosition(sourceFile: LineMapSource, position: number): LineAndCharacter;
export function getLineAndCharacterOfPosition(sourceFile: SourceFileLike, position: number): LineAndCharacter; // eslint-disable-line @typescript-eslint/unified-signatures
export function getLineAndCharacterOfPosition(sourceFile: LineMapSource, position: number): LineAndCharacter {
    return computeLineAndCharacterOfPosition(getLineStarts(sourceFile), position);
}
